PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS schema_migrations (id INTEGER PRIMARY KEY AUTOINCREMENT, version TEXT NOT NULL UNIQUE, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended','pending')), last_login_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_users_status ON users(status);
CREATE TABLE IF NOT EXISTS roles (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL UNIQUE, label TEXT NOT NULL, is_system INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS permissions (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL UNIQUE, label TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS user_roles (user_id INTEGER NOT NULL, role_id INTEGER NOT NULL, PRIMARY KEY(user_id,role_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS role_permissions (role_id INTEGER NOT NULL, permission_id INTEGER NOT NULL, PRIMARY KEY(role_id,permission_id), FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE CASCADE, FOREIGN KEY(permission_id) REFERENCES permissions(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS academic_years (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL UNIQUE, starts_on TEXT, ends_on TEXT, is_active INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS departments (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, code TEXT UNIQUE);
CREATE TABLE IF NOT EXISTS classes (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, department_id INTEGER, FOREIGN KEY(department_id) REFERENCES departments(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS sections (id INTEGER PRIMARY KEY AUTOINCREMENT, class_id INTEGER NOT NULL, name TEXT NOT NULL, UNIQUE(class_id,name), FOREIGN KEY(class_id) REFERENCES classes(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS batches (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, academic_year_id INTEGER, class_id INTEGER, section_id INTEGER, FOREIGN KEY(academic_year_id) REFERENCES academic_years(id) ON DELETE SET NULL, FOREIGN KEY(class_id) REFERENCES classes(id) ON DELETE SET NULL, FOREIGN KEY(section_id) REFERENCES sections(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS semesters (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, academic_year_id INTEGER, starts_on TEXT, ends_on TEXT, FOREIGN KEY(academic_year_id) REFERENCES academic_years(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS subjects (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, code TEXT UNIQUE, description TEXT, thumbnail TEXT, status TEXT NOT NULL DEFAULT 'active', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS courses (id INTEGER PRIMARY KEY AUTOINCREMENT, subject_id INTEGER NOT NULL, title TEXT NOT NULL, description TEXT, teacher_id INTEGER, status TEXT NOT NULL DEFAULT 'draft', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY(subject_id) REFERENCES subjects(id) ON DELETE CASCADE, FOREIGN KEY(teacher_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS enrollments (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, course_id INTEGER NOT NULL, batch_id INTEGER, enrolled_at TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'active', UNIQUE(user_id,course_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(course_id) REFERENCES courses(id) ON DELETE CASCADE, FOREIGN KEY(batch_id) REFERENCES batches(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS course_sections (id INTEGER PRIMARY KEY AUTOINCREMENT, course_id INTEGER NOT NULL, title TEXT NOT NULL, sort_order INTEGER NOT NULL DEFAULT 0, FOREIGN KEY(course_id) REFERENCES courses(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS lessons (id INTEGER PRIMARY KEY AUTOINCREMENT, course_section_id INTEGER NOT NULL, title TEXT NOT NULL, content TEXT, objectives TEXT, instructions TEXT, duration_minutes INTEGER, sort_order INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'draft', release_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY(course_section_id) REFERENCES course_sections(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS learning_materials (id INTEGER PRIMARY KEY AUTOINCREMENT, lesson_id INTEGER NOT NULL, original_name TEXT NOT NULL, stored_name TEXT NOT NULL, mime_type TEXT NOT NULL, size_bytes INTEGER NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY(lesson_id) REFERENCES lessons(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS lesson_progress (user_id INTEGER NOT NULL, lesson_id INTEGER NOT NULL, completed_at TEXT, progress_percent INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(user_id,lesson_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(lesson_id) REFERENCES lessons(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS attendance_sessions (id INTEGER PRIMARY KEY AUTOINCREMENT, course_id INTEGER, batch_id INTEGER, session_date TEXT NOT NULL, period_label TEXT, marked_by INTEGER NOT NULL, created_at TEXT NOT NULL, UNIQUE(course_id,batch_id,session_date,period_label), FOREIGN KEY(course_id) REFERENCES courses(id) ON DELETE SET NULL, FOREIGN KEY(batch_id) REFERENCES batches(id) ON DELETE SET NULL, FOREIGN KEY(marked_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS attendance_records (session_id INTEGER NOT NULL, student_id INTEGER NOT NULL, status TEXT NOT NULL, note TEXT, PRIMARY KEY(session_id,student_id), FOREIGN KEY(session_id) REFERENCES attendance_sessions(id) ON DELETE CASCADE, FOREIGN KEY(student_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS attendance_corrections (id INTEGER PRIMARY KEY AUTOINCREMENT, session_id INTEGER NOT NULL, student_id INTEGER NOT NULL, old_status TEXT NOT NULL, new_status TEXT NOT NULL, reason TEXT NOT NULL, corrected_by INTEGER NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY(session_id) REFERENCES attendance_sessions(id) ON DELETE CASCADE, FOREIGN KEY(student_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(corrected_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS question_banks (id INTEGER PRIMARY KEY AUTOINCREMENT, course_id INTEGER, name TEXT NOT NULL, created_by INTEGER NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY(course_id) REFERENCES courses(id) ON DELETE SET NULL, FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS questions (id INTEGER PRIMARY KEY AUTOINCREMENT, question_bank_id INTEGER NOT NULL, type TEXT NOT NULL, prompt TEXT NOT NULL, answer_text TEXT, marks REAL NOT NULL DEFAULT 1, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY(question_bank_id) REFERENCES question_banks(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS question_options (id INTEGER PRIMARY KEY AUTOINCREMENT, question_id INTEGER NOT NULL, option_text TEXT NOT NULL, is_correct INTEGER NOT NULL DEFAULT 0, sort_order INTEGER NOT NULL DEFAULT 0, FOREIGN KEY(question_id) REFERENCES questions(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS quizzes (id INTEGER PRIMARY KEY AUTOINCREMENT, course_id INTEGER NOT NULL, title TEXT NOT NULL, duration_minutes INTEGER, total_marks REAL, pass_marks REAL, attempt_limit INTEGER NOT NULL DEFAULT 1, starts_at TEXT, ends_at TEXT, status TEXT NOT NULL DEFAULT 'draft', created_at TEXT NOT NULL, FOREIGN KEY(course_id) REFERENCES courses(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS quiz_questions (quiz_id INTEGER NOT NULL, question_id INTEGER NOT NULL, sort_order INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(quiz_id,question_id), FOREIGN KEY(quiz_id) REFERENCES quizzes(id) ON DELETE CASCADE, FOREIGN KEY(question_id) REFERENCES questions(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS exam_attempts (id INTEGER PRIMARY KEY AUTOINCREMENT, quiz_id INTEGER NOT NULL, user_id INTEGER NOT NULL, started_at TEXT NOT NULL, expires_at TEXT NOT NULL, submitted_at TEXT, status TEXT NOT NULL DEFAULT 'in_progress', score REAL, UNIQUE(quiz_id,user_id,started_at), FOREIGN KEY(quiz_id) REFERENCES quizzes(id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS exam_answers (id INTEGER PRIMARY KEY AUTOINCREMENT, attempt_id INTEGER NOT NULL, question_id INTEGER NOT NULL, answer_text TEXT, awarded_marks REAL, saved_at TEXT NOT NULL, UNIQUE(attempt_id,question_id), FOREIGN KEY(attempt_id) REFERENCES exam_attempts(id) ON DELETE CASCADE, FOREIGN KEY(question_id) REFERENCES questions(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS exam_events (id INTEGER PRIMARY KEY AUTOINCREMENT, attempt_id INTEGER NOT NULL, event_type TEXT NOT NULL, metadata_json TEXT, created_at TEXT NOT NULL, FOREIGN KEY(attempt_id) REFERENCES exam_attempts(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS projects (id INTEGER PRIMARY KEY AUTOINCREMENT, course_id INTEGER NOT NULL, title TEXT NOT NULL, instructions TEXT, project_type TEXT NOT NULL DEFAULT 'individual', starts_at TEXT, deadline_at TEXT, max_upload_bytes INTEGER, status TEXT NOT NULL DEFAULT 'draft', created_at TEXT NOT NULL, FOREIGN KEY(course_id) REFERENCES courses(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS project_submissions (id INTEGER PRIMARY KEY AUTOINCREMENT, project_id INTEGER NOT NULL, user_id INTEGER NOT NULL, version_no INTEGER NOT NULL DEFAULT 1, status TEXT NOT NULL DEFAULT 'draft', submitted_at TEXT, feedback TEXT, marks REAL, UNIQUE(project_id,user_id,version_no), FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS submission_files (id INTEGER PRIMARY KEY AUTOINCREMENT, submission_id INTEGER NOT NULL, original_name TEXT NOT NULL, stored_name TEXT NOT NULL, mime_type TEXT NOT NULL, size_bytes INTEGER NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY(submission_id) REFERENCES project_submissions(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS grades (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, course_id INTEGER NOT NULL, item_type TEXT NOT NULL, item_id INTEGER NOT NULL, marks REAL, max_marks REAL, graded_by INTEGER, graded_at TEXT, UNIQUE(user_id,item_type,item_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(course_id) REFERENCES courses(id) ON DELETE CASCADE, FOREIGN KEY(graded_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS feature_settings (id INTEGER PRIMARY KEY AUTOINCREMENT, feature_key TEXT NOT NULL UNIQUE, enabled INTEGER NOT NULL DEFAULT 0, config_json TEXT, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS app_settings (id INTEGER PRIMARY KEY AUTOINCREMENT, setting_key TEXT NOT NULL UNIQUE, setting_value TEXT, is_public INTEGER NOT NULL DEFAULT 0, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS notifications (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, title TEXT NOT NULL, body TEXT NOT NULL, read_at TEXT, created_at TEXT NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS audit_logs (id INTEGER PRIMARY KEY AUTOINCREMENT, actor_user_id INTEGER, action TEXT NOT NULL, description TEXT NOT NULL, entity_type TEXT, entity_id INTEGER, ip_address TEXT, created_at TEXT NOT NULL, FOREIGN KEY(actor_user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS mfa_credentials (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL UNIQUE, encrypted_secret TEXT NOT NULL, recovery_codes_json TEXT, last_used_step INTEGER, enabled_at TEXT, updated_at TEXT NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS login_attempts (id INTEGER PRIMARY KEY AUTOINCREMENT, email TEXT NOT NULL, ip_address TEXT NOT NULL, successful INTEGER NOT NULL DEFAULT 0, attempted_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_login_attempt_lookup ON login_attempts(email,ip_address,attempted_at);
